draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw heart
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.bezierCurveTo(W/2 - 40, H/2 - 100, W/2 + 40, H/2 - 100, W/2, H/2 - 50);
  ctx.bezierCurveTo(W/2 + 40, H/2, W/2 + 60, H/2 + 30, W/2, H/2 + 60);
  ctx.bezierCurveTo(W/2 - 60, H/2 + 30, W/2 - 40, H/2, W/2, H/2 - 50);
  ctx.stroke();

  // draw trans fat molecule
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2 - 20, 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2 + 20, 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 - 40, H/2, 10, 0, Math.PI * 2);
  ctx.fill();

  // draw warning sign
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.rect(W/2 + 50, H/2 - 50, 50, 50);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('X', W/2 + 75, H/2);

  // animate trans fat molecule
  ctx.save();
  ctx.translate(W/2 - 100, H/2);
  ctx.rotate(Math.sin(t));
  ctx.translate(-W/2 + 100, -H/2);
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 10, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  ctx.restore();
}
